<script>
 import {layout,inspectorMax,coverflowMax,saveLayout,resetLayout} from '../layout.svelte';import {onMount} from 'svelte';import {FolderOpen} from 'lucide-svelte';import {studio,run,refresh,notify} from '../studio.svelte';import {api,persist,isTeam,isMock} from '../api';import {getSettingsApi} from '../services/settings.ts';
 let root=$state(studio.dataRoot),tools=$state(null),notifications=$state(typeof Notification!=='undefined'?Notification.permission:'unavailable');onMount(()=>{getSettingsApi().tools().then(value=>tools=value).catch(()=>{});});
</script>
<section class="settings-block"><h2>工作区</h2>{#if studio.projectWarnings.length}<div role="alert"><h3>需要检查的项目</h3><p>这些项目未能加载，原文件仍保留。请从备份恢复项目文件，或选择其他数据目录。</p>{#each studio.projectWarnings as warning}<p class="field-error project-warning-detail">{warning}</p>{/each}</div>{/if}<div class="field-grid"><label>右侧面板宽度（像素）<input aria-label="右侧面板宽度（像素）" type="number" min="220" max={inspectorMax()} value={Math.min(layout.inspectorWidth,inspectorMax())} onchange={e=>{layout.inspectorWidth=Math.min(inspectorMax(),Math.max(220,Number(e.target.value)||280));saveLayout();}}/></label><label>图片浏览区高度（像素）<input aria-label="图片浏览区高度（像素）" type="number" min="100" max={coverflowMax()} value={Math.min(layout.coverflowHeight,coverflowMax())} onchange={e=>{layout.coverflowHeight=Math.min(coverflowMax(),Math.max(100,Number(e.target.value)||144));saveLayout();}}/></label></div><button class="text-button" onclick={resetLayout}>恢复默认布局</button>{#if !isTeam}<label>主机数据目录<div class="input-action"><input aria-label="主机数据目录" bind:value={root}/><button aria-label="选择数据目录" onclick={()=>run("正在选择文件夹",async()=>{const path=await api('pick_output');if(path)root=path;})}><FolderOpen size={16}/></button></div></label><button class="line-button" disabled={!root||root===studio.dataRoot||!!studio.busy} onclick={()=>run("正在切换工作区",async()=>{await api('data_root_switch',{path:root});studio.pid='';studio.aid='';studio.drafts={};studio.selected=[];await refresh();notify("工作区已切换");})}>使用此目录</button>{/if}<label>画布<select bind:value={studio.background} onchange={()=>persist('background',studio.background)}><option value="paper">浅色</option><option value="checker">透明网格</option><option value="dark">深色</option></select></label><label>桌面通知<button class="line-button" disabled={notifications==='granted'||notifications==='unavailable'} onclick={async()=>notifications=await Notification.requestPermission()}>{notifications==='granted'?"已启用":"启用通知"}</button></label><label>预览加速<select aria-label="预览加速" bind:value={studio.gpuPreviewEnabled} onchange={()=>persist('gpu-preview-enabled',studio.gpuPreviewEnabled)}><option value={true}>优先使用显卡</option><option value={false}>兼容模式</option></select></label><div class="status-line"><span>当前预览方式</span><b>{studio.previewEngine==='gpu'?"显卡加速已就绪":studio.previewEngine==='cpu'?'CPU':"正在检查"}</b></div><h3>本地处理工具</h3><div class="status-line"><span>图像处理引擎</span><b class:connected={!isMock}>{isMock?'模拟模式':'就绪'}</b></div><div class="status-line"><span>OpenCV</span><b>{tools?(tools.available?"就绪":"不可用"):"正在检查"}</b></div>{#if tools&&!tools.available}<p class="hint">{tools.error||tools.message||"降噪工具不可用，请联系主机管理员检查 OpenCV。"}</p>{/if}</section>
